window.ZUMDAHL_COURSE_DATA = {"sourceTitle":"Chemistry, Seventh Edition","authors":"Steven S. Zumdahl and Susan A. Zumdahl","units":[{"title":"Foundations and Chemical Reactions","chapters":[{"number":1,"title":"Chemical Foundations","sections":[{"title":"Chemistry: An Overview","topics":[]},{"title":"The Scientific Method","topics":[]},{"title":"Units of Measurement","topics":[]},{"title":"Uncertainty in Measurement","topics":[]},{"title":"Significant Figures and Calculations","topics":[]},{"title":"Dimensional Analysis","topics":[]},{"title":"Temperature","topics":[]},{"title":"Density","topics":[]},{"title":"Classification of Matter","topics":[]}],"focusAreas":["Chemistry: An Overview","The Scientific Method","Units of Measurement","Uncertainty in Measurement","Significant Figures and Calculations","Dimensional Analysis","Temperature","Density","Classification of Matter"],"vocabulary":[["Accuracy","The agreement of a particular value with the true value."],["Chemical change","The change of substances into other substances through a reorganization of the atoms; a chemical reaction."],["Chromatography","The general name for a series of methods for separating mixtures by employing a system with a mobile phase and a stationary phase."],["Compound","A substance with constant composition that can be broken down into elements by chemical processes."],["Density","A property of matter representing the mass per unit volume."],["Distillation","A method for separating the components of a liquid mixture that depends on differences in the ease of vaporization of the components."],["Exponential notation","Nexpresses a number as 10,a convenient method for representing a very large or very small number and for easily indicating the number of significant figures."],["Filtration","A method for separating the components of a mixture containing a solid and a liquid."],["Hypothesis","One or more assumptions put forth to explain the observed behavior of nature."],["Law of conservation of mass","Mass is neither created nor destroyed."],["Mass","The quantity of matter in an object."],["Matter","The material of the universe."],["Model (theory)","A set of assumptions put forth to explain the observed behavior of matter. The models of chemistry usually involve assumptions about the behavior of individual atoms or molecules."],["Natural law","A statement that expresses generally observed behavior."],["Precision","The degree of agreement among several measurements of the same quantity; the reproducibility of a measurement."],["Pure substance","A substance with constant composition."],["Random error","An error that has an equal probability of being high or low."],["Scientific method","The process of studying natural phenomena, involving observations, forming laws and theories, and testing of theories by experimentation."],["SI system","International System of units based on the metric system and units derived from the metric system."],["Significant figures","The certain digits and the first uncertain digit of a measurement."],["Solution","A homogeneous mixture."],["States of matter","The three different forms in which matter can exist; solid,liquid,and gas."],["Systematic error","An error that always occurs in the same direction."],["Theory","A set of assumptions put forth to explain some aspect of the observed behavior of matter."],["Uncertainty (in measurement)","The characteristic that any measurement involves estimates and cannot be exactly reproduced."],["Unit factor method","An equivalence statement between units used for converting from one unit to another."]],"equations":[["Density","d = m/V","Use it to relate a sample's mass and volume."],["Kelvin conversion","K = °C + 273.15","Use it to convert Celsius temperature to the absolute temperature scale."]]},{"number":2,"title":"Atoms, Molecules, and Ions","sections":[{"title":"The Early History of Chemistry","topics":[]},{"title":"Fundamental Chemical Laws","topics":[]},{"title":"Dalton’s Atomic Theory","topics":[]},{"title":"Early Experiments to Characterize the Atom","topics":[]},{"title":"The Modern View of Atomic Structure: An Introduction","topics":[]},{"title":"Molecules and Ions","topics":[]},{"title":"An Introduction to the Periodic Table","topics":[]},{"title":"Naming Simple Compounds","topics":[]}],"focusAreas":["The Early History of Chemistry","Fundamental Chemical Laws","Dalton’s Atomic Theory","Early Experiments to Characterize the Atom","The Modern View of Atomic Structure: An Introduction","Molecules and Ions","An Introduction to the Periodic Table","Naming Simple Compounds"],"vocabulary":[["Acid","A substance that produces hydrogen ions in solution; a proton donor."],["Alkali metal","A Group 1A metal."],["Alkaline earth metal","A Group 2A metal."],["Anion","A negative ion."],["Atomic number","The number of protons in the nucleus of an atom."],["Atomic weight","The weighted average mass of the atoms in a naturally occurring element."],["Ball-and-stick model","A molecular model that distorts the sizes of atoms but shows bond relationships clearly."],["Binary compound","A twoelement compound."],["Cathode rays","The “rays” emanating from the negative electrode (cathode) in a partially evacuated tube; a stream of electrons."],["Cation","A positive ion."],["Chemical bond","The force or,more accurately,the energy,that holds two atoms together in a compound."],["Chemical formula","The representation of a molecule in which the symbols for the elements are used to indicate the types of atoms present and subscripts are used to show the relative numbers of atoms."],["Covalent bonding","A type of bonding in which electrons are shared by atoms."],["Electron","A negatively charged particle that moves around the nucleus of an atom."],["Group (of the periodic table)","A vertical column of elements having the same valence electron configuration and showing similar properties."],["Halogen","A Group 7A element."],["Ion","An atom or a group of atoms that has a net positive or negative charge."],["Ionic bonding","The electrostatic attraction between oppositely charged ions."],["Ionic solid (salt)","A solid containing cations and anions that dissolves in water to give a solution containing the separated ions which are mobile and thus free to conduct electrical current."],["Isotopes","Atoms of the same element (the same number of protons) with different numbers of neutrons. They have identical atomic numbers but different mass numbers."],["Law of conservation of mass","Mass is neither created nor destroyed."],["Law of multiple proportions","A law stating that when two elements form a series of compounds,the ratios of the masses of the second element that combine with one gram of the first element can always be reduced to small whole numbers."],["Metal","An element that gives up electrons relatively easily and is lustrous,malleable,and a good conductor of heat and electricity."],["Molecule","A bonded collection of two or more atoms of the same or different elements."],["Neutron","A particle in the atomic nucleus with mass virtually equal to the proton’s but with no charge."],["Noble gas","A Group 8A element."],["Nonmetal","An element not exhibiting metallic characteristics. Chemically,a typical nonmetal accepts electrons from a metal."],["Nuclear atom","An atom having a dense center of positive charge (the nucleus) with electrons moving around the outside."],["Nucleus","The small, dense center of positive charge in an atom."],["Periodic table","A chart showing all the elements arranged in columns with similar chemical properties."],["Polyatomic ion","An ion containing a number of atoms."],["Proton","A positively charged particle in an atomic nucleus."],["Radioactive decay (radioactivity)","The spontaneous decomposition of a nucleus to form a different nucleus."],["Space-filling model","A model of a molecule showing the relative sizes of the atoms and their relative orientations."],["Structural formula","The representation of a molecule in which the relative positions of the atoms are shown and the bonds are indicated by lines."]],"equations":[]},{"number":3,"title":"Stoichiometry","sections":[{"title":"Counting by Weighing","topics":[]},{"title":"Atomic Masses","topics":[]},{"title":"The Mole","topics":[]},{"title":"Molar Mass","topics":[]},{"title":"Percent Composition of Compounds","topics":[]},{"title":"Determining the Formula of a Compound","topics":[]},{"title":"Chemical Equations","topics":[]},{"title":"Balancing Chemical Equations","topics":[]},{"title":"Stoichiometric Calculations: Amounts of Reactants and Products","topics":[]},{"title":"Calculations Involving a Limiting Reactant","topics":[]}],"focusAreas":["Counting by Weighing","Atomic Masses","The Mole","Molar Mass","Percent Composition of Compounds","Determining the Formula of a Compound","Chemical Equations","Balancing Chemical Equations","Stoichiometric Calculations: Amounts of Reactants and Products","Calculations Involving a Limiting Reactant"],"vocabulary":[["Chemical equation","A representation of a chemical reaction showing the relative numbers of reactant and product molecules."],["Chemical stoichiometry","The calculation of the quantities of material consumed and produced in chemical reactions."],["Empirical formula","The simplest whole number ratio of atoms in a compound."],["Haber process","The manufacture of ammonia from nitrogen and hydrogen,carried out at high pressure and high temperature with the aid of a catalyst."],["Limiting reactant (limiting reagent)","The reactant that is completely consumed when a reaction is run to completion."],["Mass percent","The percent by mass of a component of a mixture (11.1) or of a given element in a compound."],["Mass spectrometer","An instrument used to determine the relative masses of atoms by the deflection of their ions on a magnetic field."],["Molar mass","The mass in grams of one mole of molecules or formula molecular weight.units of a substance; also called"],["Mole ratio (stoichiometry)","The ratio of moles of one substance to moles of another substance in a balanced chemical equation."],["Molecular formula","The exact formula of a molecule,giving the types of atoms and the number of each type."],["Percent yield","The actual yield of a product as a percentage of the theoretical yield."],["Product","A substance resulting from a chemical reaction. It is shown to the right of the arrow in a chemical equation."],["Reactant","A starting substance in a chemical reaction. It appears to the left of the arrow in a chemical equation."],["Theoretical yield","The maximum amount of a given product that can be formed when the limiting reactant is completely consumed."]],"equations":[["Amount from mass","n = m/M","Use it to convert a sample mass to moles using molar mass."],["Percent composition","% element = (mass of element / mass of compound) × 100","Use it to determine a compound's elemental mass percentages."],["Percent yield","% yield = (actual yield / theoretical yield) × 100","Use it to compare experimental product with the stoichiometric maximum."]]},{"number":4,"title":"Types of Chemical Reactions and Solution Stoichiometry","sections":[{"title":"Water, the Common Solvent","topics":[]},{"title":"The Nature of Aqueous Solutions: Strong and Weak Electrolytes","topics":[]},{"title":"The Composition of Solutions","topics":[]},{"title":"Types of Chemical Reactions","topics":[]},{"title":"Precipitation Reactions","topics":[]},{"title":"Describing Reactions in Solution","topics":[]},{"title":"Stoichiometry of Precipitation Reactions","topics":[]},{"title":"Acid–Base Reactions","topics":[]},{"title":"Oxidation–Reduction Reactions","topics":[]},{"title":"Balancing Oxidation–Reduction Equations","topics":[]}],"focusAreas":["Water, the Common Solvent","The Nature of Aqueous Solutions: Strong and Weak Electrolytes","The Composition of Solutions","Types of Chemical Reactions","Precipitation Reactions","Describing Reactions in Solution","Stoichiometry of Precipitation Reactions","Acid–Base Reactions","Oxidation–Reduction Reactions","Balancing Oxidation–Reduction Equations"],"vocabulary":[["Acid","A substance that produces hydrogen ions in solution; a proton donor."],["Aqueous solution","A solution in which water is the dissolving medium or solvent."],["Complete ionic equation","An equation that shows all substances that are strong electrolytes as ions."],["Dilution","The process of adding solvent to lower the concentration of solute in a solution."],["Electrical conductivity","The ability to conduct an electric current."],["Electrolyte","A material that dissolves in water to give a solution that conducts an electric current."],["Endpoint","The point in a titration at which the indicator changes color."],["Equivalence point (stoichiometric point)","The point in a titration when enough titrant has been added to react exactly with the substance in solution being titrated."],["Formula equation","An equation representing a reaction in solution showing the reactants and products in undissociated form,whether they are strong or weak electrolytes."],["Half-reactions","The two parts of an oxidation–reduction reaction,one representing oxidation,the other reduction."],["Hydration","The interaction between solute particles and water molecules."],["Indicator","A chemical that changes color and is used to mark the end point of a titration."],["Molarity","Moles of solute per volume of solution in liters."],["Net ionic equation","An equation for a reaction in solution, where strong electrolytes are written as ions,showing only those components that are directly involved in the chemical change."],["Neutralization reaction","An acid–base reaction."],["Nonelectrolyte","A substance that,when dissolved in water,gives a nonconducting solution."],["Oxidation","An increase in oxidation state (a loss of electrons)."],["Oxidation–reduction (redox) reaction","A reaction in which one or more electrons are transferred."],["Oxidation states","A concept that provides a way to keep track of electrons in oxidation–reduction reactions according to certain rules."],["Oxidizing agent (electron acceptor)","A reactant that accepts electrons from another reactant."],["Polar molecule","A molecule that has a permanent dipole moment."],["Reducing agent (electron donor)","A reactant that donates electrons to another substance to reduce the oxidation state of one of its atoms."],["Selective precipitation","A method of separating metal ions from an aqueous mixture by using a reagent whose anion forms a precipitate with only one or a few of the ions in the mixture."],["Solubility","The amount of a substance that dissolves in a given volume of solvent at a given temperature."],["Solute","A substance dissolved in a liquid to form a solution."],["Solvent","The dissolving medium in a solution."],["Spectator ions","Ions present in solution that do not participate directly in a reaction."],["Standard solution","A solution whose concentration is accurately known."],["Strong acid","An acid that completely dissociates to produce an H ion and the conjugate base."],["Strong base","A metal hydroxide salt that completely dissociates into its ions in water."],["Strong electrolyte","A material that, when dissolved in water, gives a solution that conducts an electric current very efficiently."],["Titration","A technique in which one solution is used to analyze another."],["Volumetric analysis","A process involving titration of one solution with another."],["Weak acid","An acid that dissociates only slightly in aqueous solution."],["Weak base","A base that reacts with water to produce hydroxide ions to only a slight extent in aqueous solution."],["Weak electrolyte","A material which,when dissolved in water,gives a solution that conducts only a small electric current."]],"equations":[["Molarity","M = moles of solute / liters of solution","Use it to express solution concentration."],["Dilution relation","M₁V₁ = M₂V₂","Use it when solvent is added without changing moles of solute."]]}]},{"title":"Gases, Energy, and Atomic Structure","chapters":[{"number":5,"title":"Gases","sections":[{"title":"Pressure","topics":[]},{"title":"The Gas Laws of Boyle, Charles, and Avogadro","topics":[]},{"title":"The Ideal Gas Law","topics":[]},{"title":"Gas Stoichiometry","topics":[]},{"title":"Dalton’s Law of Partial Pressures","topics":[]},{"title":"The Kinetic Molecular Theory of Gases","topics":[]},{"title":"Effusion and Diffusion","topics":[]},{"title":"Real Gases","topics":[]},{"title":"Characteristics of Several Real Gases","topics":[]},{"title":"Chemistry in the Atmosphere","topics":[]}],"focusAreas":["Pressure","The Gas Laws of Boyle, Charles, and Avogadro","The Ideal Gas Law","Gas Stoichiometry","Dalton’s Law of Partial Pressures","The Kinetic Molecular Theory of Gases","Effusion and Diffusion","Real Gases","Characteristics of Several Real Gases","Chemistry in the Atmosphere"],"vocabulary":[["Acid rain","A result of air pollution by sulfur dioxide."],["Air pollution","Contamination of the atmosphere,mainly by the gaseous products of transportation and production of electricity."],["Atmosphere","The mixture of gases that surrounds the earth’s surface."],["Avogadro’s law","Equal volumes of gases at the same temperature and pressure contain the same number of particles."],["Boyle’s law","The volume of a given sample of gas at constant temperature varies inversely with the pressure."],["Charles’s law","The volume of a given sample of gas at constant pressure is directly proportional to the temperature in kelvins."],["Dalton’s law of partial pressures","For a mixture of gases in a container, the total pressure exerted is the sum of the pressures that each gas would exert if it were alone."],["Diffusion","The mixing of gases."],["Effusion","The passage of a gas through a tiny orifice into an evacuated chamber."],["Graham’s law of effusion","The rate of effusion of a gas is inversely proportional to the square root of the mass of its particles."],["Kinetic molecular theory (KMT)","A model that assumes that an ideal gas is composed of tiny particles (molecules) in constant motion."],["Manometer","A device for measuring the pressure of a gas in a container."],["Molar volume","The volume of one mole of an ideal gas; equal to 22.42 liters at STP."],["Mole fraction","The ratio of the number of moles of a given component in a mixture to the total number of moles in the mixture."],["Partial pressures","The independent pressures exerted by different gases in a mixture."],["Pascal","The SI unit of pressure; equal to newtons per meter squared."],["Photochemical smog","Air pollution produced by the action of light on oxygen, nitrogen oxides, and unburned fuel from auto exhaust to form ozone and other pollutants."],["Root mean square velocity","The square root of the average of the squares of the individual velocities of gas particles."],["Standard atmosphere","A unit of pressure equal to 760 mm Hg."],["Standard temperature and pressure (STP)","The condition 0°C and 1 atmosphere of pressure."],["Torr","Another name for millimeter of mercury (mm Hg)."],["Van der Waals equation","A mathematical expression for describing the behavior of real gases."]],"equations":[["Boyle's law","P₁V₁ = P₂V₂","Use it for pressure-volume changes at constant temperature and amount."],["Charles's law","V₁/T₁ = V₂/T₂","Use it for volume-temperature changes at constant pressure and amount."],["Combined gas law","P₁V₁/T₁ = P₂V₂/T₂","Use it when pressure, volume, and temperature all change for a fixed gas sample."],["Ideal gas law","PV = nRT","Use it to connect gas pressure, volume, amount, and absolute temperature."],["Dalton's law","Ptotal = ΣPi","Use it to find total pressure from component partial pressures."],["Graham's law","rate₁/rate₂ = √(M₂/M₁)","Use it to compare effusion rates of gases with different molar masses."],["van der Waals equation","[P + a(n/V)²](V - nb) = nRT","Use it to model real gases by correcting for attractions and molecular volume."]]},{"number":6,"title":"Thermochemistry","sections":[{"title":"The Nature of Energy","topics":[]},{"title":"Enthalpy and Calorimetry","topics":[]},{"title":"Hess’s Law","topics":[]},{"title":"Standard Enthalpies of Formation","topics":[]},{"title":"Present Sources of Energy","topics":[]},{"title":"New Energy Sources","topics":[]}],"focusAreas":["The Nature of Energy","Enthalpy and Calorimetry","Hess’s Law","Standard Enthalpies of Formation","Present Sources of Energy","New Energy Sources"],"vocabulary":[["Calorimetry","The science of measuring heat flow."],["Endothermic","Refers to a reaction where energy (as heat) flows into the system."],["Enthalpy","E PV Ea property of a system equal to, where is the Pinternal energy of the system, is the pressure of the system,and V is the volume of the system. At constant pressure the change in enthalpy equals the energy flow as heat."],["First law of thermodynamics","The energy of the universe is constant; same as the law of conservation of energy."],["Fossil fuel","Coal, petroleum, or natural gas; consists of carbonbased molecules derived from decomposition of onceliving organisms."],["Greenhouse effect","A warming effect exerted by the earth’s atmosphere (particularly CO and H O) due to thermal energy retained 2 2 by absorption of infrared radiation."],["Heat","Energy transferred between two objects due to a temperature difference between them."],["Heat capacity","The amount of energy required to raise the temperature of an object by one degree Celsius."],["Hess’s law","In going from a particular set of reactants to a particular set of products,the enthalpy change is the same whether the reaction takes place in one step or in a series of steps; in summary,enthalpy is a state function."],["Kinetic energy","Mv( ) energy due to the motion of an object; depen-2 dent on the mass of the object and the square of its velocity."],["Law of conservation of energy","Energy can be converted from one form to another but can be neither created nor destroyed."],["Molar heat capacity","The energy required to raise the temperature of one mole of a substance by one degree Celsius."],["Potential energy","Energy due to position or composition."],["Specific heat capacity","The energy required to raise the temperature of one gram of a substance by one degree Celsius."],["Standard enthalpy of formation","The enthalpy change that accompanies the formation of one mole of a compound at 25°C from its elements, with all substances in their standard states at that temperature."],["Standard state","A reference state for a specific substance defined according to a set of conventional definitions."],["State function (property)","A property that is independent of the pathway."],["Surroundings","Everything in the universe surrounding a thermodynamic system."],["Syngas","Synthetic gas, a mixture of carbon monoxide and hydrogen, obtained by coal gasification."],["System (thermodynamic)","That part of the universe on which attention is to be focused."],["Thermodynamics","The study of energy and its interconversions."]],"equations":[["First Law","ΔE = q + w","Use it to account for heat and work contributions to internal-energy change."],["Pressure-volume work","w = -PΔV","Use it for expansion or compression against constant external pressure."],["Calorimetry","q = mcΔT","Use it to calculate heat from mass, specific heat, and temperature change."],["Hess's law","ΔHoverall = ΣΔHsteps","Use it to combine known reactions to obtain an unknown enthalpy change."],["Formation-enthalpy relation","ΔH°rxn = ΣnΔH°f(products) - ΣnΔH°f(reactants)","Use it to calculate reaction enthalpy from standard formation enthalpies."]]},{"number":7,"title":"Atomic Structure and Periodicity","sections":[{"title":"Electromagnetic Radiation","topics":[]},{"title":"The Nature of Matter","topics":[]},{"title":"The Atomic Spectrum of Hydrogen","topics":[]},{"title":"The Bohr Model","topics":[]},{"title":"The Quantum Mechanical Model of the Atom","topics":[]},{"title":"Quantum Numbers","topics":[]},{"title":"Orbital Shapes and Energies","topics":[]},{"title":"Electron Spin and the Pauli Principle","topics":[]},{"title":"Polyelectronic Atoms","topics":[]},{"title":"The History of the Periodic Table","topics":[]},{"title":"The Aufbau Principle and the Periodic Table","topics":[]},{"title":"Periodic Trends in Atomic Properties","topics":[]},{"title":"The Properties of a Group: The Alkali Metals","topics":[]}],"focusAreas":["Electromagnetic Radiation","The Nature of Matter","The Atomic Spectrum of Hydrogen","The Bohr Model","The Quantum Mechanical Model of the Atom","Quantum Numbers","Orbital Shapes and Energies","Electron Spin and the Pauli Principle","Polyelectronic Atoms","The History of the Periodic Table","The Aufbau Principle and the Periodic Table","Periodic Trends in Atomic Properties","The Properties of a Group: The Alkali Metals"],"vocabulary":[["Actinide series","A group of 14 elements following actinium in the fperiodic table, in which the 5 orbitals are being filled."],["Atomic radius","Half the distance between the nuclei in a molecule consisting of identical atoms."],["Aufbau principle","The principle stating that as protons are added one by one to the nucleus to build up the elements,electrons are similarly added to hydrogenlike orbitals."],["Continuous spectrum","A spectrum that exhibits all the wavelengths of visible light."],["Core electron","An inner electron in an atom; one not in the outermost (valence) principal quantum level."],["Degenerate orbitals","A group of orbitals with the same energy."],["Dual nature of light","The statement that light exhibits both wave and particulate properties."],["Electromagnetic radiation","Radiant energy that exhibits wavelike behavior and travels through space at the speed of light in a vacuum."],["Electron affinity","The energy change associated with the addition of an electron to a gaseous atom."],["Frequency","The number of waves (cycles) per second that pass a given point in space."],["Heisenberg uncertainty principle","A principle stating that there is a fundamental limitation to how precisely both the position and momentum of a particle can be known at a given time."],["Hund’s rule","The lowest energy configuration for an atom is the one having the maximum number of unpaired electrons allowed by the Pauli exclusion principle in a particular set of degenerate orbitals, with all unpaired electrons having parallel spins."],["Lanthanide series","A group of 14 elements following lanthanum in fthe periodic table, in which the 4 orbitals are being filled."],["Line spectrum","A spectrum showing only certain discrete wavelengths."],["Main-group (representative) elements","Elements in the groups labeled 1A,2A,3A,4A,5A,6A,7A,and 8A in the periodic table. The group s pnumber gives the sum of the valence and electrons."],["Metalloids (semimetals)","Elements along the division line in the periodic table between metals and nonmetals. These elements exhibit both metallic and nonmetallic properties."],["Node","An area of an orbital having zero electron probability."],["Orbital","A specific wave function for an electron in an atom. The square of this function gives the probability distribution for the electron."],["Pauli exclusion principle","In a given atom no two electrons can have the same set of four quantum numbers."],["Photon","A quantum of electromagnetic radiation."],["Polyelectronic atom","An atom with more than one electron."],["Principal quantum number (n)","The quantum number relating to the size and energy of an orbital; it can have any positive integer value."],["Probability distribution","The square of the wave function indicating the probability of finding an electron at a particular point in space."],["Standing wave","A stationary wave as on a string of a musical instrument; in the wave mechanical model,the electron in the hydrogen atom is considered to be a standing wave."],["Subshell","A set of orbitals with a given azimuthal quantum number."],["Transition metals","Several series of elements in which inner orbitals d f( or orbitals) are being filled."],["Valence electrons","The electrons in the outermost principal quantum level of an atom."],["Wave function","A function of the coordinates of an electron’s position in threedimensional space that describes the properties of the electron."],["Wave mechanical model","A model for the hydrogen atom in which the electron is assumed to behave as a standing wave."],["Wavelength","The distance between two consecutive peaks or troughs in a wave."]],"equations":[["Wave relation","c = λν","Use it to connect wavelength and frequency of electromagnetic radiation."],["Photon energy","E = hν","Use it to calculate the energy of one photon."],["de Broglie relation","λ = h/(mv)","Use it to determine the wavelength associated with a moving particle."],["Hydrogen energy levels","En = -2.178 × 10⁻¹⁸ J / n²","Use it to calculate allowed electron energies in hydrogen."],["Rydberg transition","ΔE = -2.178 × 10⁻¹⁸ J(1/nf² - 1/ni²)","Use it to calculate the energy change for a hydrogen electron transition."]]},{"number":8,"title":"Bonding: General Concepts","sections":[{"title":"Types of Chemical Bonds","topics":[]},{"title":"Electronegativity","topics":[]},{"title":"Bond Polarity and Dipole Moments","topics":[]},{"title":"Ions: Electron Configurations and Sizes","topics":[]},{"title":"Energy Effects in Binary Ionic Compounds","topics":[]},{"title":"Partial Ionic Character of Covalent Bonds","topics":[]},{"title":"The Covalent Chemical Bond: A Model","topics":[]},{"title":"Covalent Bond Energies and Chemical Reactions","topics":[]},{"title":"The Localized Electron Bonding Model","topics":[]},{"title":"Lewis Structures","topics":[]},{"title":"Exceptions to the Octet Rule","topics":[]},{"title":"Resonance","topics":[]},{"title":"Molecular Structure: The VSEPR Model","topics":[]}],"focusAreas":["Types of Chemical Bonds","Electronegativity","Bond Polarity and Dipole Moments","Ions: Electron Configurations and Sizes","Energy Effects in Binary Ionic Compounds","Partial Ionic Character of Covalent Bonds","The Covalent Chemical Bond: A Model","Covalent Bond Energies and Chemical Reactions","The Localized Electron Bonding Model","Lewis Structures","Exceptions to the Octet Rule","Resonance","Molecular Structure: The VSEPR Model"],"vocabulary":[["Bond energy","The energy required to break a given chemical bond."],["Bond length","The distance between the nuclei of the two atoms connected by a bond; the distance where the total energy of a diatomic molecule is minimal."],["Bonding pair","An electron pair found in the space between two atoms."],["Coulomb’s law","E E2.31 10, where is the energy r rof interaction between a pair of ions, expressed in joules; is the Q Qdistance between the ion centers in nm; and and are the nu-1 2 merical ion charges."],["Covalent bonding","A type of bonding in which electrons are shared by atoms."],["Dipole moment","A property of a molecule whose charge distribution can be represented by a center of positive charge and a center of negative charge."],["Double bond","A bond in which two pairs of electrons are shared by two atoms."],["Electronegativity","The tendency of an atom in a molecule to attract shared electrons to itself."],["Ionic bonding","The electrostatic attraction between oppositely charged ions."],["Ionic compound (binary)","A compound that results when a metal reacts with a nonmetal to form a cation and an anion."],["Isoelectronic ions","Ions containing the same number of electrons."],["Lattice energy","The energy change occurring when separated gaseous ions are packed together to form an ionic solid."],["Lewis structure","A diagram of a molecule showing how the valence electrons are arranged among the atoms in the molecule."],["Localized electron (LE) model","A model which assumes that a molecule is composed of atoms that are bound together by sharing pairs of electrons using the atomic orbitals of the bound atoms."],["Lone pair","An electron pair that is localized on a given atom; an electron pair not involved in bonding."],["Molecular structure","The threedimensional arrangement of atoms in a molecule."],["Octet rule","The observation that atoms of nonmetals tend to form the most stable molecules when they are surrounded by eight electrons (to fill their valence orbitals)."],["Polar covalent bond","A covalent bond in which the electrons are not shared equally because one atom attracts them more strongly than the other."],["Resonance","A condition occurring when more than one valid Lewis structure can be written for a particular molecule. The actual electronic structure is not represented by any one of the Lewis structures but by the average of all of them."],["Triple bond","A bond in which three pairs of electrons are shared by two atoms."],["Valence shell electron-pair repulsion (VSEPR) model","A model whose main postulate is that the structure around a given atom in a molecule is determined principally by minimizing electronpair repulsions."]],"equations":[["Formal charge","formal charge = valence e⁻ - lone-pair e⁻ - ½(bonding e⁻)","Use it to compare plausible Lewis structures."],["Bond-enthalpy estimate","ΔHrxn ≈ ΣD(bonds broken) - ΣD(bonds formed)","Use it to estimate reaction enthalpy from average bond energies."]]},{"number":9,"title":"Covalent Bonding: Orbitals","sections":[{"title":"Hybridization and the Localized Electron Model","topics":[]},{"title":"The Molecular Orbital Model","topics":[]},{"title":"Bonding in Homonuclear Diatomic Molecules","topics":[]},{"title":"Bonding in Heteronuclear Diatomic Molecules","topics":[]},{"title":"Combining the Localized Electron and Molecular Orbital Models","topics":[]}],"focusAreas":["Hybridization and the Localized Electron Model","The Molecular Orbital Model","Bonding in Homonuclear Diatomic Molecules","Bonding in Heteronuclear Diatomic Molecules","Combining the Localized Electron and Molecular Orbital Models"],"vocabulary":[["Antibonding molecular orbital","An orbital higher in energy than the atomic orbitals of which it is composed."],["Bond order","The difference between the number of bonding electrons and the number of antibonding electrons, divided by two. It is an index of bond strength."],["Bonding molecular orbital","An orbital lower in energy than the atomic orbitals of which it is composed."],["Diamagnetism","A type of magnetism,associated with paired electrons, that causes a substance to be repelled from the inducing magnetic field."],["Hybrid orbitals","A set of atomic orbitals adopted by an atom in a molecule different from those of the atom in the free state."],["Hybridization","A mixing of the native orbitals on a given atom to form special atomic orbitals for bonding."],["Paramagnetism","A type of induced magnetism, associated with unpaired electrons,that causes a substance to be attracted into the inducing magnetic field."],["Pi (π) bond","Pa covalent bond in which parallel orbitals share an electron pair occupying the space above and below the line joining the atoms."],["Sigma (σ) bond","A covalent bond in which the electron pair is shared in an area centered on a line running between the atoms."],["hybrid orbital","An orbital formed by mixing atomic orbitals on the same atom to describe localized bonding."],["sp hybridization","Mixing one s and one p orbital to produce two linear hybrid orbitals."],["sp2 hybridization","Mixing one s and two p orbitals to produce three trigonal-planar hybrid orbitals."],["sp3 hybridization","Mixing one s and three p orbitals to produce four tetrahedrally directed hybrid orbitals."]],"equations":[["Molecular-orbital bond order","bond order = ½(bonding e⁻ - antibonding e⁻)","Use it to predict relative bond stability and strength in the MO model."]]}]},{"title":"States of Matter, Solutions, and Kinetics","chapters":[{"number":10,"title":"Liquids and Solids","sections":[{"title":"Intermolecular Forces","topics":[]},{"title":"The Liquid State","topics":[]},{"title":"An Introduction to Structures and Types of Solids","topics":[]},{"title":"Structure and Bonding in Metals","topics":[]},{"title":"Carbon and Silicon: Network Atomic Solids","topics":[]},{"title":"Molecular Solids","topics":[]},{"title":"Ionic Solids","topics":[]},{"title":"Vapor Pressure and Changes of State","topics":[]},{"title":"Phase Diagrams","topics":[]}],"focusAreas":["Intermolecular Forces","The Liquid State","An Introduction to Structures and Types of Solids","Structure and Bonding in Metals","Carbon and Silicon: Network Atomic Solids","Molecular Solids","Ionic Solids","Vapor Pressure and Changes of State","Phase Diagrams"],"vocabulary":[["Alloy","A substance that contains a mixture of elements and has metallic properties."],["Amorphous solid","A solid with considerable disorder in its structure."],["Atomic solid","A solid that contains atoms at the lattice points."],["Band model","A molecular model for metals in which the electrons are assumed to travel around the metal crystal in molecular orbitals formed from the valence atomic orbitals of the metal atoms."],["Capillary action","The spontaneous rising of a liquid in a narrow tube."],["Ceramic","A nonmetallic material made from clay and hardened by firing at high temperature; it contains minute silicate crystals suspended in a glassy cement."],["Condensation","The process by which vapor molecules reform a liquid."],["Condensed states of matter","Liquids and solids."],["Critical point","The point on a phase diagram at which the temperature and pressure have their critical values; the end point of the liquid–vapor line."],["Critical pressure","The minimum pressure required to produce liquefaction of a substance at the critical temperature."],["Critical temperature","The temperature above which vapor cannot be liquefied no matter what pressure is applied."],["Crystalline solid","A solid with a regular arrangement of its components."],["Cubic closest packed (ccp) structure","A solid modeled by the closabcabcest packing of spheres with an arrangement of layers; the unit cell is facecentered cubic."],["Dipole–dipole attraction","The attractive force resulting when polar molecules line up so that the positive and negative ends are close to each other."],["Enthalpy (heat) of fusion","The enthalpy change that occurs to melt a solid at its melting point."],["Glass","An amorphous solid obtained when silica is mixed with other compounds,heated above its melting point,and then cooled rapidly."],["Heat of fusion","The enthalpy change that occurs to melt a solid at its melting point."],["Heat of vaporization","The energy required to vaporize one mole of a liquid at a pressure of one atmosphere."],["Heating curve","A plot of temperature versus time for a substance where energy is added at a constant rate."],["Hydrogen bonding","Unusually strong dipole–dipole attractions that occur among molecules in which hydrogen is bonded to a highly electronegative atom."],["Intermolecular forces","Relatively weak interactions that occur between molecules."],["Ionic solid (salt)","A solid containing cations and anions that dissolves in water to give a solution containing the separated ions which are mobile and thus free to conduct electrical current."],["Lattice","A threedimensional system of points designating the positions of the centers of the components of a solid (atoms, ions,or molecules)."],["London dispersion forces","The forces,existing among noble gas atoms and nonpolar molecules, that involve an accidental dipole that induces a momentary dipole in a neighbor."],["Molecular solid","A solid composed of neutral molecules at the lattice points."],["Network solid","An atomic solid containing strong directional covalent bonds."],["Normal boiling point","The temperature at which the vapor pressure of a liquid is exactly one atmosphere."],["Normal melting point","The temperature at which the solid and liquid states have the same vapor pressure under conditions where the total pressure on the system is one atmosphere."],["Phase diagram","A convenient way of representing the phases of a substance in a closed system as a function of temperature and pressure."],["Semiconductor","A substance conducting only a slight electrical current at room temperature, but showing increased conductivity at higher temperatures."],["Silica","The fundamental silicon–oxygen compound,which has the empirical formula SiO,and forms the basis of quartz and certain types 2 of sand."],["Silicates","Salts that contain metal cations and polyatomic silicon– oxygen anions that are usually polymeric."],["Sublimation","The process by which a substance goes directly from the solid to the gaseous state without passing through the liquid state."],["Supercooling","The process of cooling a liquid below its freezing point without its changing to a solid."],["Surface tension","The resistance of a liquid to an increase in its surface area."],["Triple point","The point on a phase diagram at which all three states of a substance are present."],["Unit cell","The smallest repeating unit of a lattice."],["Vapor pressure","The pressure of the vapor over a liquid at equilibrium."],["Vaporization (evaporization)","The change in state that occurs when a liquid evaporates to form a gas."],["Viscosity","The resistance of a liquid to flow."],["X-ray diffraction","A technique for establishing the structure of crystalline solids by directing X rays of a single wavelength at a crystal and obtaining a diffraction pattern from which interatomic spaces can be determined."]],"equations":[["Clausius-Clapeyron equation","ln(P₂/P₁) = -(ΔHvap/R)(1/T₂ - 1/T₁)","Use it to relate vapor pressure at two temperatures."],["Bragg equation","nλ = 2d sin θ","Use it to determine crystal-plane spacing from X-ray diffraction."]]},{"number":11,"title":"Properties of Solutions","sections":[{"title":"Solution Composition","topics":[]},{"title":"The Energies of Solution Formation","topics":[]},{"title":"Factors Affecting Solubility","topics":[]},{"title":"The Vapor Pressures of Solutions","topics":[]},{"title":"Boiling-Point Elevation and Freezing-Point Depression","topics":[]},{"title":"Osmotic Pressure","topics":[]},{"title":"Colligative Properties of Electrolyte Solutions","topics":[]},{"title":"Colloids","topics":[]}],"focusAreas":["Solution Composition","The Energies of Solution Formation","Factors Affecting Solubility","The Vapor Pressures of Solutions","Boiling-Point Elevation and Freezing-Point Depression","Osmotic Pressure","Colligative Properties of Electrolyte Solutions","Colloids"],"vocabulary":[["Coagulation","The destruction of a colloid by causing particles to aggregate and settle out."],["Colligative properties","Properties of a solution that depend only on the number,and not on the identity,of the solute particles."],["Desalination","The removal of dissolved salts from an aqueous solution."],["Dialysis","A phenomenon in which a semipermeable membrane allows transfer of both solvent molecules and small solute molecules and ions."],["Heat of hydration","The enthalpy change associated with placing gaseous molecules or ions in water; the sum of the energy needed to expand the solvent and the energy released from the solvent–solute interactions."],["Heat of solution","The enthalpy change associated with dissolving a solute in a solvent; the sum of the energies needed to expand both solvent and solute in a solution and the energy released from the solvent–solute interactions."],["Henry’s law","The amount of a gas dissolved in a solution is directly proportional to the pressure of the gas above the solution."],["Ideal solution","A solution whose vapor pressure is directly proportional to the mole fraction of solvent present."],["Ion pairing","A phenomenon occurring in solution when oppositely charged ions aggregate and behave as a single particle."],["Isotonic solutions","Solutions having identical osmotic pressures."],["Molal boiling-point elevation constant","A constant characteristic of a particular solvent that gives the change in boiling point as a function of solution molality; used in molecular weight determinations."],["Molal freezing-point depression constant","A constant characteristic of a particular solvent that gives the change in freezing point as a function of the solution molality; used in molecular weight determinations"],["Molality","The number of moles of solute per kilogram of solvent in a solution."],["Molarity","Moles of solute per volume of solution in liters."],["Mole fraction","The ratio of the number of moles of a given component in a mixture to the total number of moles in the mixture."],["Normality","The number of equivalents of a substance dissolved in a liter of solution."],["Raoult’s law","The vapor pressure of a solution is directly proportional to the mole fraction of solvent present."],["Reverse osmosis","The process occurring when the external pressure on a solution causes a net flow of solvent through a semipermeable membrane from the solution to the solvent."],["Semipermeable membrane","A membrane that allows solvent but not solute molecules to pass through."],["Solute","A substance dissolved in a liquid to form a solution."],["Thermal pollution","The oxygendepleting effect on lakes and rivers of using water for industrial cooling and returning it to its natural source at a higher temperature."],["Tyndall effect","The scattering of light by particles in a suspension."],["Van’t Hoff factor","The ratio of moles of particles in solution to moles of solute dissolved."]],"equations":[["Mole fraction","χi = ni/ntotal","Use it to express a component's fraction of total moles."],["Raoult's law","Pi = χiP°i","Use it to calculate a volatile component's partial pressure in an ideal solution."],["Boiling-point elevation","ΔTb = Kb m","Use it to calculate boiling-point change from solute molality."],["Freezing-point depression","ΔTf = Kf m","Use it to calculate freezing-point change from solute molality."],["Osmotic pressure","Π = MRT","Use it to connect osmotic pressure with dilute-solution concentration and temperature."]]},{"number":12,"title":"Chemical Kinetics","sections":[{"title":"Reaction Rates","topics":[]},{"title":"Rate Laws: An Introduction","topics":[]},{"title":"Determining the Form of the Rate Law","topics":[]},{"title":"The Integrated Rate Law","topics":[]},{"title":"Rate Laws: A Summary","topics":[]},{"title":"Reaction Mechanisms","topics":[]},{"title":"A Model for Chemical Kinetics","topics":[]},{"title":"Catalysis","topics":[]}],"focusAreas":["Reaction Rates","Rate Laws: An Introduction","Determining the Form of the Rate Law","The Integrated Rate Law","Rate Laws: A Summary","Reaction Mechanisms","A Model for Chemical Kinetics","Catalysis"],"vocabulary":[["Activated complex (transition state)","The arrangement of atoms found at the top of the potential energy barrier as a reaction proceeds from reactants to products."],["Activation energy","The threshold energy that must be overcome to produce a chemical reaction."],["Adsorption","The collection of one substance on the surface of another."],["Bimolecular step","A reaction involving the collision of two molecules."],["Catalyst","A substance that speeds up a reaction without being consumed."],["Chemical kinetics","The area of chemistry that concerns reaction rates."],["Collision model","A model based on the idea that molecules must collide to react; used to account for the observed characteristics of reaction rates."],["Differential rate law","An expression that gives the rate of a reaction as a function of concentrations; often called the rate law."],["Enzyme","A large molecule,usually a protein,that catalyzes biological reactions."],["Half-life (of a reactant)","The time required for a reactant to reach half of its original concentration."],["Integrated rate law","An expression that shows the concentration of a reactant as a function of time."],["Intermediate","A species that is neither a reactant nor a product but that is formed and consumed in the reaction sequence."],["Molecularity","The number of species that must collide to produce the reaction represented by an elementary step in a reaction mechanism."],["Order (of reactant)","The positive or negative exponent, determined by experiment, of the reactant concentration in a rate law."],["Rate constant","The proportionality constant in the relationship between reaction rate and reactant concentrations."],["Rate-determining step","The slowest step in a reaction mechanism,the one determining the overall rate."],["Rate law (differential rate law)","An expression that shows how the rate of reaction depends on the concentration of reactants."],["Reaction mechanism","The series of elementary steps involved in a chemical reaction."],["Reaction rate","The change in concentration of a reactant or product per unit time."],["Steric factor","The factor (always less than 1) that reflects the fraction of collisions with orientations that can produce a chemical reaction."],["Termolecular step","A reaction involving the simultaneous collision of three molecules."],["Unimolecular step","A reaction step involving only one molecule."]],"equations":[["Differential rate law","rate = k[A]ᵐ[B]ⁿ","Use it to relate reaction rate to reactant concentrations."],["First-order integrated rate law","ln[A]t = -kt + ln[A]₀","Use it to find concentration or time for a first-order reaction."],["First-order half-life","t½ = 0.693/k","Use it to find the concentration-independent half-life of a first-order process."],["Second-order integrated rate law","1/[A]t = kt + 1/[A]₀","Use it for a second-order reaction in one reactant."],["Arrhenius equation","ln k = -Ea/(RT) + ln A","Use it to describe how the rate constant depends on temperature."]]}]},{"title":"Equilibrium, Thermodynamics, and Electrochemistry","chapters":[{"number":13,"title":"Chemical Equilibrium","sections":[{"title":"The Equilibrium Condition","topics":[]},{"title":"The Equilibrium Constant","topics":[]},{"title":"Equilibrium Expressions Involving Pressures","topics":[]},{"title":"Heterogeneous Equilibria","topics":[]},{"title":"Applications of the Equilibrium Constant","topics":[]},{"title":"Solving Equilibrium Problems","topics":[]},{"title":"Le Châtelier’s Principle","topics":[]}],"focusAreas":["The Equilibrium Condition","The Equilibrium Constant","Equilibrium Expressions Involving Pressures","Heterogeneous Equilibria","Applications of the Equilibrium Constant","Solving Equilibrium Problems","Le Châtelier’s Principle"],"vocabulary":[["Chemical equilibrium","A dynamic reaction system in which the concentrations of all reactants and products remain constant as a function of time."],["Equilibrium constant","The value obtained when equilibrium concentrations of the chemical species are substituted in the equilibrium expression."],["Equilibrium expression","The expression (from the law of mass action) obtained by multiplying the product concentrations and dividing by the multiplied reactant concentrations, with each concentration raised to a power represented by the coefficient in the balanced equation."],["Equilibrium position","A particular set of equilibrium concentrations."],["Heterogeneous equilibrium","An equilibrium involving reactants and/or products in more than one phase."],["Homogeneous equilibrium","An equilibrium system where all reactants and products are in the same phase."],["Law of mass action","A general description of the equilibrium condition; it defines the equilibrium constant expression."],["Le Châtelier’s principle","If a change is imposed on a system at equilibrium,the position of the equilibrium will shift in a direction that tends to reduce the effect of that change."],["Reaction quotient, Q","A quotient obtained by applying the law of mass action to initial concentrations rather than to equilibrium concentrations."],["dynamic equilibrium","A state in which forward and reverse reactions continue at equal rates, leaving concentrations constant."],["reaction quotient","An expression with the form of the equilibrium constant evaluated using current, not necessarily equilibrium, amounts."],["ICE table","An organizational table that tracks initial, change, and equilibrium concentrations during an equilibrium calculation."],["Le Chatelier's principle","A system at equilibrium shifts in the direction that partially counteracts an imposed change."]],"equations":[["Concentration equilibrium constant","Kc = product concentrations / reactant concentrations","Use it to describe an equilibrium mixture using molar concentrations and stoichiometric powers."],["Pressure equilibrium constant","Kp = product partial pressures / reactant partial pressures","Use it for gas-phase equilibria expressed with partial pressures."],["Reaction quotient","Q = current product terms / current reactant terms","Use it to predict which direction a nonequilibrium mixture will shift."]]},{"number":14,"title":"Acids and Bases","sections":[{"title":"The Nature of Acids and Bases","topics":[]},{"title":"Acid Strength","topics":[]},{"title":"The pH Scale","topics":[]},{"title":"Calculating the pH of Strong Acid Solutions","topics":[]},{"title":"Calculating the pH of Weak Acid Solutions","topics":[]},{"title":"Bases","topics":[]},{"title":"Polyprotic Acids","topics":[]},{"title":"Acid–Base Properties of Salts","topics":[]},{"title":"The Effect of Structure on Acid–Base Properties","topics":[]},{"title":"Acid–Base Properties of Oxides","topics":[]},{"title":"The Lewis Acid–Base Model","topics":[]},{"title":"Strategy for Solving Acid–Base Problems: A Summary","topics":[]}],"focusAreas":["The Nature of Acids and Bases","Acid Strength","The pH Scale","Calculating the pH of Strong Acid Solutions","Calculating the pH of Weak Acid Solutions","Bases","Polyprotic Acids","Acid–Base Properties of Salts","The Effect of Structure on Acid–Base Properties","Acid–Base Properties of Oxides","The Lewis Acid–Base Model","Strategy for Solving Acid–Base Problems: A Summary"],"vocabulary":[["Acidic oxide","A covalent oxide that dissolves in water to give an acidic solution."],["Arrhenius concept","A concept postulating that acids produce hydrogen ions in aqueous solution,while bases produce hydroxide ions."],["Autoionization","The transfer of a proton from one molecule to another of the same substance."],["Basic oxide","An ionic oxide that dissolves in water to produce a basic solution."],["Brønsted–Lowry model","A model proposing that an acid is a proton donor,and a base is a proton acceptor."],["Conjugate acid","The species formed when a proton is added to a base."],["Conjugate acid–base pair","Two species related to each other by the donating and accepting of a single proton."],["Conjugate base","What remains of an acid molecule after a proton is lost."],["Lewis acid","An electronpair acceptor."],["Lewis base","An electronpair donor."],["Lime–soda process","A watersoftening method in which lime and soda ash are added to water to remove calcium and magnesium ions by precipitation."],["Major species","The components present in relatively large amounts in a solution."],["Monoprotic acid","An acid with one acidic proton."],["Organic acid","An acid with a carbonatom backbone; often contains the carboxyl group."],["Oxyacid","An acid in which the acidic proton is attached to an oxygen atom."],["Percent dissociation","The ratio of the amount of a substance that is dissociated at equilibrium to the initial concentration of the substance in a solution,multiplied by 100."],["pH scale","A log scale based on 10 and equal to log[H ]; a convenient way to represent solution acidity."],["Polyprotic acid","An acid with more than one acidic proton. It dissociates in a stepwise manner,one proton at a time."],["Salt","An ionic compound."],["Strong acid","An acid that completely dissociates to produce an H ion and the conjugate base."],["Strong base","A metal hydroxide salt that completely dissociates into its ions in water."],["Weak acid","An acid that dissociates only slightly in aqueous solution."],["Weak base","A base that reacts with water to produce hydroxide ions to only a slight extent in aqueous solution."]],"equations":[["pH","pH = -log[H⁺]","Use it to express hydrogen-ion concentration on a logarithmic scale."],["pOH","pOH = -log[OH⁻]","Use it to express hydroxide-ion concentration on a logarithmic scale."],["Water ion product","Kw = [H⁺][OH⁻]","Use it to connect hydrogen- and hydroxide-ion concentrations."],["Acid dissociation constant","Ka = [H⁺][A⁻]/[HA]","Use it to quantify weak-acid ionization."],["Base dissociation constant","Kb = [BH⁺][OH⁻]/[B]","Use it to quantify weak-base ionization."],["Conjugate relation","KaKb = Kw","Use it to connect the strengths of a conjugate acid-base pair."]]},{"number":15,"title":"Applications of Aqueous Equilibria","sections":[{"title":"Solutions of Acids or Bases Containing a Common Ion","topics":[]},{"title":"Buffered Solutions","topics":[]},{"title":"Buffering Capacity","topics":[]},{"title":"Titrations and pH Curves","topics":[]},{"title":"Acid-Base Indicators","topics":[]},{"title":"Solubility Equilibria and the Solubility Product","topics":[]},{"title":"Precipitation and Qualitative Analysis","topics":[]},{"title":"Equilibria Involving Complex Ions","topics":[]}],"focusAreas":["Solutions of Acids or Bases Containing a Common Ion","Buffered Solutions","Buffering Capacity","Titrations and pH Curves","Acid-Base Indicators","Solubility Equilibria and the Solubility Product","Precipitation and Qualitative Analysis","Equilibria Involving Complex Ions"],"vocabulary":[["Acid–base indicator","A substance that marks the end point of an acid–base titration by changing color."],["Buffered solution","A solution that resists a change in its pH when either hydroxide ions or protons are added."],["Common ion effect","The shift in an equilibrium position caused by the addition or presence of an ion involved in the equilibrium reaction."],["Complex ion","A charged species consisting of a metal ion surrounded by ligands."],["Equivalence point (stoichiometric point)","The point in a titration when enough titrant has been added to react exactly with the substance in solution being titrated."],["Formation constant (stability constant)","The equilibrium constant for each step of the formation of a complex ion by the addition of an individual ligand to a metal ion or complex ion in aqueous solution."],["Indicator","A chemical that changes color and is used to mark the end point of a titration."],["Selective precipitation","A method of separating metal ions from an aqueous mixture by using a reagent whose anion forms a precipitate with only one or a few of the ions in the mixture."],["Solubility product constant","The constant for the equilibrium expression representing the dissolving of an ionic solid in water."],["buffering capacity","The amount of added acid or base a buffer can absorb before its pH changes substantially."],["acid-base titration","A controlled neutralization used to determine an unknown acid or base amount from a standard solution."],["equivalence point","The titration point at which stoichiometrically equivalent amounts of acid and base have reacted."],["molar solubility","The number of moles of a solid that dissolve per liter of saturated solution."],["qualitative analysis","Identification of ions through a planned sequence of selective chemical reactions."],["ligand","A Lewis base that donates an electron pair to a metal ion to form a coordinate bond."],["formation constant","The equilibrium constant for formation of a complex ion from a metal ion and its ligands."]],"equations":[["Henderson-Hasselbalch equation","pH = pKa + log([A⁻]/[HA])","Use it to estimate the pH of a buffer."],["Solubility product","Ksp = product of dissolved-ion concentrations","Use it to describe equilibrium between a sparingly soluble solid and its ions."],["Formation constant","Kf = [complex ion] / reactant concentration terms","Use it to quantify complex-ion formation."]]},{"number":16,"title":"Spontaneity, Entropy, and Free Energy","sections":[{"title":"Spontaneous Processes and Entropy","topics":[]},{"title":"Entropy and the Second Law of Thermodynamics","topics":[]},{"title":"The Effect of Temperature on Spontaneity","topics":[]},{"title":"Free Energy","topics":[]},{"title":"Entropy Changes in Chemical Reactions","topics":[]},{"title":"Free Energy and Chemical Reactions","topics":[]},{"title":"The Dependence of Free Energy on Pressure","topics":[]},{"title":"Free Energy and Equilibrium","topics":[]},{"title":"Free Energy and Work","topics":[]}],"focusAreas":["Spontaneous Processes and Entropy","Entropy and the Second Law of Thermodynamics","The Effect of Temperature on Spontaneity","Free Energy","Entropy Changes in Chemical Reactions","Free Energy and Chemical Reactions","The Dependence of Free Energy on Pressure","Free Energy and Equilibrium","Free Energy and Work"],"vocabulary":[["Entropy","A thermodynamic function that measures randomness or disorder."],["Equilibrium point (thermodynamic definition)","The position where the free energy of a reaction system has its lowest possible value."],["Irreversible process","Any real process. When a system undergoes the changes State 1 State 2 State 1 by any real pathway,the unin n verse is different than before the cyclic process took place in the system."],["Positional probability","A type of probability that depends on the number of arrangements in space that yield a particular state."],["Reversible process","A cyclic process carried out by a hypothetical pathway,which leaves the universe exactly the same as it was before the process. No real process is reversible."],["Second law of thermodynamics","In any spontaneous process, there is always an increase in the entropy of the universe."],["Spontaneous process","A process that occurs without outside intervention."],["Standard free energy change","The change in free energy that will occur for one unit of reaction if the reactants in their standard states are converted to products in their standard states."],["Standard free energy of formation","The change in free energy that accompanies the formation of one mole of a substance from its constituent elements with all reactants and products in their standard states."],["Third law of thermodynamics","The entropy of a perfect crystal at 0K is zero."],["microstate","One specific microscopic arrangement consistent with a system's macroscopic state."],["Gibbs free energy","A state function that predicts spontaneity at constant temperature and pressure."]],"equations":[["Entropy change of the universe","ΔSuniv = ΔSsystem + ΔSsurroundings","Use it to test spontaneity: a spontaneous process has positive ΔSuniv."],["Gibbs free energy","ΔG = ΔH - TΔS","Use it to predict spontaneity at constant temperature and pressure."],["Standard free energy and equilibrium","ΔG° = -RT ln K","Use it to connect thermodynamic favorability with the equilibrium constant."],["Nonstandard free energy","ΔG = ΔG° + RT ln Q","Use it to determine reaction direction away from standard conditions."]]},{"number":17,"title":"Electrochemistry","sections":[{"title":"Galvanic Cells","topics":[]},{"title":"Standard Reduction Potentials","topics":[]},{"title":"Cell Potential, Electrical Work, and Free Energy","topics":[]},{"title":"Dependence of Cell Potential on Concentration","topics":[]},{"title":"Batteries","topics":[]},{"title":"Corrosion","topics":[]},{"title":"Electrolysis","topics":[]},{"title":"Commercial Electrolytic Processes","topics":[]}],"focusAreas":["Galvanic Cells","Standard Reduction Potentials","Cell Potential, Electrical Work, and Free Energy","Dependence of Cell Potential on Concentration","Batteries","Corrosion","Electrolysis","Commercial Electrolytic Processes"],"vocabulary":[["Ampere","The unit of electric current equal to one coulomb of charge per second."],["Anode","The electrode in a galvanic cell at which oxidation occurs."],["Cathode","The electrode in a galvanic cell at which reduction occurs."],["Cathodic protection","A method in which an active metal,such asmagnesium, is connected to steel to protect it from corrosion."],["Cell potential (electromotive force)","The driving force in a galvanic cell that pulls electrons from the reducing agent in one compartment to the oxidizing agent in the other."],["Chlor–alkali process","The process for producing chlorine and sodium hydroxide by electrolyzing brine in a mercury cell."],["Concentration cell","A galvanic cell in which both compartments contain the same components, but at different concentrations."],["Downs cell","A cell used for electrolyzing molten sodium chloride."],["Dry cell battery","A common battery used in calculators,watches,radios,and tape players."],["Electrochemistry","The study of the interchange of chemical and electrical energy."],["Electrolysis","A process that involves forcing a current through a cell to cause a nonspontaneous chemical reaction to occur."],["Electrolytic cell","A cell that uses electrical energy to produce a chemical change that would otherwise not occur spontaneously."],["Faraday","A constant representing the charge on one mole of electrons; 96,485 coulombs."],["Fuel cell","A galvanic cell for which the reactants are continuously supplied."],["Galvanic cell","A device in which chemical energy from a spontaneous redox reaction is changed to electrical energy that can be used to do work."],["Half-reactions","The two parts of an oxidation–reduction reaction,one representing oxidation,the other reduction."],["Ion-selective electrode","An electrode sensitive to the concentration of a particular ion in solution."],["Lead storage battery","A battery (used in cars) in which the anode is lead, the cathode is lead coated with lead dioxide, and the electrolyte is a sulfuric acid solution."],["Oxidation","An increase in oxidation state (a loss of electrons)."],["Oxidation–reduction (redox) reaction","A reaction in which one or more electrons are transferred."],["Oxidizing agent (electron acceptor)","A reactant that accepts electrons from another reactant."],["Porous disk","A disk in a tube connecting two different solutions in a galvanic cell that allows ion flow without extensive mixing of the solutions."],["Reducing agent (electron donor)","A reactant that donates electrons to another substance to reduce the oxidation state of one of its atoms."],["Salt bridge","A U-tube containing an electrolyte that connects the two compartments of a galvanic cell,allowing ion flow without extensive mixing of the different solutions."],["Standard reduction potential","The potential of a halfreaction under standard state conditions, as measured against the potential of the standard hydrogen electrode."],["Volt","The unit of electrical potential defined as one joule of work per coulomb of charge transferred."],["Voltmeter","An instrument that measures cell potential by drawing electric current through a known resistance."]],"equations":[["Standard cell potential","E°cell = E°cathode - E°anode","Use it to calculate voltage from standard reduction potentials."],["Electrical work and free energy","ΔG = -nFE","Use it to connect cell potential with reaction free-energy change."],["Nernst equation","E = E° - (RT/nF)ln Q","Use it to calculate cell potential under nonstandard conditions."],["Electrolysis charge relation","charge = current × time","Use it to determine charge passed during electrolysis."]]}]},{"title":"Nuclear, Inorganic, and Organic Chemistry","chapters":[{"number":18,"title":"The Nucleus: A Chemist’s View","sections":[{"title":"Nuclear Stability and Radioactive Decay","topics":[]},{"title":"The Kinetics of Radioactive Decay","topics":[]},{"title":"Nuclear Transformations","topics":[]},{"title":"Detection and Uses of Radioactivity","topics":[]},{"title":"Thermodynamic Stability of the Nucleus","topics":[]},{"title":"Nuclear Fission and Nuclear Fusion","topics":[]},{"title":"Effects of Radiation","topics":[]}],"focusAreas":["Nuclear Stability and Radioactive Decay","The Kinetics of Radioactive Decay","Nuclear Transformations","Detection and Uses of Radioactivity","Thermodynamic Stability of the Nucleus","Nuclear Fission and Nuclear Fusion","Effects of Radiation"],"vocabulary":[["Alpha (α) particle","A helium nucleus."],["Alpha-particle production","A common mode of decay for radioactive nuclides in which the mass number changes."],["Atomic number","The number of protons in the nucleus of an atom."],["Beta (β) particle","An electron produced in radioactive decay."],["Beta-particle production","A decay process for radioactive nuclides in which the mass number remains constant and the atomic number changes. The net effect is to change a neutron to a proton."],["Binding energy (nuclear)","The energy required to decompose a nucleus into its component nucleons."],["Breeder reactor","A nuclear reactor in which fissionable fuel is produced while the reactor runs."],["Chain reaction (nuclear)","A selfsustaining fission process caused by the production of neutrons that proceed to split other nuclei."],["Control rods","Rods in a nuclear reactor composed of substances that absorb neutrons. These rods regulate the power level of the reactor."],["Critical reaction (nuclear)","A reaction in which exactly one neutron from each fission event causes another fission event, thus sustaining the chain reaction."],["Cyclotron","A type of particle accelerator in which an ion introduced at the center is accelerated in an expanding spiral path by the use of alternating electrical fields in the presence of a magnetic field."],["Electron capture","A process in which one of the innerorbital electrons in an atom is captured by the nucleus."],["Fission","The process of using a neutron to split a heavy nucleus into two nuclei with smaller mass numbers."],["Fusion","The process of combining two light nuclei to form a heavier, more stable nucleus."],["Gamma (γ) ray","A highenergy photon."],["Geiger–Müller counter (Geiger counter)","An instrument that measures the rate of radioactive decay based on the ions and electrons produced as a radioactive particle passes through a gasfilled chamber."],["Half-life (of a radioactive sample)","The time required for the number of nuclides in a radioactive sample to reach half of the original value."],["Isotopes","Atoms of the same element (the same number of protons) with different numbers of neutrons. They have identical atomic numbers but different mass numbers."],["Linear accelerator","A type of particle accelerator in which a changing electrical field is used to accelerate a positive ion along a linear path."],["Main-group (representative) elements","Elements in the groups labeled 1A,2A,3A,4A,5A,6A,7A,and 8A in the periodic table. The group s pnumber gives the sum of the valence and electrons."],["Mass defect","The change in mass occurring when a nucleus is formed from its component nucleons."],["Moderator","A substance used in a nuclear reactor to slow down the neutrons."],["Neutron","A particle in the atomic nucleus with mass virtually equal to the proton’s but with no charge."],["Nuclear transformation","The change of one element into another."],["Particle accelerator","A device used to accelerate nuclear particles to very high speeds."],["Positron production","A mode of nuclear decay in which a particle is formed having the same mass as an electron but opposite charge. The net effect is to change a proton to a neutron."],["Proton","A positively charged particle in an atomic nucleus."],["Rad","A unit of radiation dosage corresponding to 10 J of energy der a dposited per kilogram of tissue (from adiation bsorbed ose)."],["Radioactive decay (radioactivity)","The spontaneous decomposition of a nucleus to form a different nucleus."],["Radiotracer","A radioactive nuclide, introduced into an organism for diagnostic purposes, whose pathway can be traced by monitoring its radioactivity."],["Rate of decay","The change in the number of radioactive nuclides in a sample per unit time."],["Reactor core","The part of a nuclear reactor where the fission reaction takes place."],["Rem","A unit of radiation dosage that accounts for both the energy of the dose and its effectiveness in causing biological damage (from r e moentgen quivalent for an)."],["Scintillation counter","An instrument that measures radioactive decay by sensing the flashes of light produced in a substance by the radiation."],["Somatic damage","Radioactive damage to an organism resulting in its sickness or death."],["Spontaneous fission","The spontaneous splitting of a heavy nuclide into two lighter nuclides."],["Subcritical reaction (nuclear)","A reaction in which less than one neutron causes another fission event and the process dies out."],["Supercritical reaction (nuclear)","A reaction in which more than one neutron from each fission event causes another fission event. The process rapidly escalates to a violent explosion."],["Transuranium elements","The elements beyond uranium that are made artificially by particle bombardment."],["Zone of nuclear stability","The area encompassing the stable nuclides on a plot of their positions as a function of the number of protons and the number of neutrons in the nucleus."]],"equations":[["Radioactive decay law","ln(Nt/N₀) = -kt","Use it to calculate the amount of a radioactive nuclide remaining."],["Radioactive half-life","t½ = 0.693/k","Use it to relate a first-order decay constant to half-life."],["Mass-energy equivalence","ΔE = Δmc²","Use it to convert nuclear mass defect into binding energy."]]},{"number":19,"title":"The Representative Elements: Groups 1A Through 4A","sections":[{"title":"A Survey of the Representative Elements","topics":[]},{"title":"The Group 1A Elements","topics":[]},{"title":"Hydrogen","topics":[]},{"title":"The Group 2A Elements","topics":[]},{"title":"The Group 3A Elements","topics":[]},{"title":"The Group 4A Elements","topics":[]}],"focusAreas":["A Survey of the Representative Elements","The Group 1A Elements","Hydrogen","The Group 2A Elements","The Group 3A Elements","The Group 4A Elements"],"vocabulary":[["Actinide series","A group of 14 elements following actinium in the fperiodic table, in which the 5 orbitals are being filled."],["Alkali metal","A Group 1A metal."],["Alkaline earth metal","A Group 2A metal."],["Borane","A covalent hydride of boron."],["Hard water","Water from natural sources that contains relatively large concentrations of calcium and magnesium ions."],["Lanthanide series","A group of 14 elements following lanthanum in fthe periodic table, in which the 4 orbitals are being filled."],["Liquefaction","The transformation of a gas into a liquid."],["Metalloids (semimetals)","Elements along the division line in the periodic table between metals and nonmetals. These elements exhibit both metallic and nonmetallic properties."],["Metallurgy","The process of separating a metal from its ore and preparing it for use."],["Transition metals","Several series of elements in which inner orbitals d f( or orbitals) are being filled."],["representative element","A main-group element whose chemical behavior reflects filling of s or p valence orbitals."],["hydride","A binary compound containing hydrogen bonded to a less electronegative element."],["allotrope","One of two or more different structural forms of the same element in the same physical state."],["inert-pair effect","The increasing tendency of the outermost s-electron pair in heavier p-block elements to remain nonbonding."],["network covalent solid","A solid in which atoms are connected throughout an extended covalent-bond framework."],["silicate","A compound built from silicon-oxygen structural units, commonly based on SiO4 tetrahedra."],["metalloid","An element with properties intermediate between typical metals and nonmetals."]],"equations":[]},{"number":20,"title":"The Representative Elements: Groups 5A Through 8A","sections":[{"title":"The Group 5A Elements","topics":[]},{"title":"The Chemistry of Nitrogen","topics":[]},{"title":"The Chemistry of Phosphorus","topics":[]},{"title":"The Group 6A Elements","topics":[]},{"title":"The Chemistry of Oxygen","topics":[]},{"title":"The Chemistry of Sulfur","topics":[]},{"title":"The Group 7A Elements","topics":[]},{"title":"The Group 8A Elements","topics":[]}],"focusAreas":["The Group 5A Elements","The Chemistry of Nitrogen","The Chemistry of Phosphorus","The Group 6A Elements","The Chemistry of Oxygen","The Chemistry of Sulfur","The Group 7A Elements","The Group 8A Elements"],"vocabulary":[["Condensation reaction","A reaction in which two molecules are joined, accompanied by the elimination of a water molecule."],["Denitrification","The return of nitrogen from decomposed matter to the atmosphere by bacteria that change nitrates to nitrogen gas."],["Disproportionation reaction","A reaction in which a given element is both oxidized and reduced."],["Frasch process","The recovery of sulfur from underground deposits by melting it with hot water and forcing it to the surface by air pressure."],["Haber process","The manufacture of ammonia from nitrogen and hydrogen,carried out at high pressure and high temperature with the aid of a catalyst."],["Halogen","A Group 7A element."],["Hydrohalic acid","An aqueous solution of a hydrogen halide."],["Interhalogen compound","A compound formed by the reaction of one halogen with another."],["Nitrogen cycle","The conversion of N to nitrogencontaining com-2 pounds, followed by the return of nitrogen gas to the atmosphere by natural decay processes."],["Nitrogen fixation","The process of transforming N to nitrogen-2 containing compounds useful to plants."],["Nitrogen-fixing bacteria","Bacteria in the root nodules of plants that can convert atmospheric nitrogen to ammonia and other nitrogencontaining compounds useful to plants."],["Noble gas","A Group 8A element."],["Ostwald process","A commercial process for producing nitric acid by the oxidation of ammonia."]],"equations":[]},{"number":21,"title":"Transition Metals and Coordination Chemistry","sections":[{"title":"The Transition Metals: A Survey","topics":[]},{"title":"The First-Row Transition Metals","topics":[]},{"title":"Coordination Compounds","topics":[]},{"title":"Isomerism","topics":[]},{"title":"Bonding in Complex Ions: The Localized Electron Model","topics":[]},{"title":"The Crystal Field Model","topics":[]},{"title":"The Biologic Importance of Coordination Complexes","topics":[]},{"title":"Metallurgy and Iron and Steel Production","topics":[]}],"focusAreas":["The Transition Metals: A Survey","The First-Row Transition Metals","Coordination Compounds","Isomerism","Bonding in Complex Ions: The Localized Electron Model","The Crystal Field Model","The Biologic Importance of Coordination Complexes","Metallurgy and Iron and Steel Production"],"vocabulary":[["Basic oxygen process","A process for producing steel by oxidizing and removing the impurities in iron using a highpressure blast of oxygen."],["Bidentate ligand","A ligand that can form two bonds to a metal ion."],["Blast furnace","A furnace in which iron oxide is reduced to iron metal by using a very strong blast of hot air to produce carbon monoxide from coke,and then using this gas as a reducing agent for the iron."],["Carbon steel","An alloy of iron containing up to about 1.5% carbon."],["Chelating ligand (chelate)","A ligand having more than one atom with a lone pair that can be used to bond to a metal ion."],["Chirality","The quality of having nonsuperimposable mirror images."],["Complex ion","A charged species consisting of a metal ion surrounded by ligands."],["Coordinate covalent bond","A metal–ligand bond resulting from the interaction of a Lewis base (the ligand) and a Lewis acid (the metal ion)."],["Coordination compound","A compound composed of a complex ion and counter ions sufficient to give no net charge."],["Coordination isomerism","Isomerism in a coordination compound in which the composition of the coordination sphere of the metal ion varies."],["Coordination number","The number of bonds formed between the metal ion and the ligands in a complex ion."],["Counterions","Anions or cations that balance the charge on the complex ion in a coordination compound."],["Crystal field model","A model used to explain the magnetism and coldors of coordination complexes through the splitting of the orbital energies."],["Cyanidation","A process in which crushed gold ore is treated with an aqueous cyanide solution in the presence of air to dissolve the gold. Pure gold is recovered by reduction of the ion to the metal."],["Cytochromes","A series of ironcontaining species composed of heme and a protein. Cytochromes are the principal electrontransfer molecules in the respiratory chain."],["Direct reduction furnace","A furnace in which iron oxide is reduced to iron metal using milder reaction conditions than in a blast furnace."],["Enantiomers","Isomers that are nonsuperimposable mirror images of each other."],["Flotation process","A method of separating the mineral particles in an ore from the gangue that depends on the greater wettability of the mineral pieces."],["Gangue","The impurities (such as clay or sand) in an ore."],["Geometrical (cis–trans) isomerism","Isomerism in which atoms or groups of atoms can assume different positions around a rigid ring or bond."],["Heme","An iron complex."],["Hemoglobin","A biomolecule composed of four myoglobinlike units (proteins plus heme) that can bind and transport four oxygen molecules in the blood."],["Isomers","Species with the same formula but different properties."],["Lanthanide contraction","The decrease in the atomic radii of the lanthanide series elements,going from left to right in the periodic table."],["Lanthanide series","A group of 14 elements following lanthanum in fthe periodic table, in which the 4 orbitals are being filled."],["Leaching","The extraction of metals from ores using aqueous chemical solutions."],["Ligand","A neutral molecule or ion having a lone pair of electrons that can be used to form a bond to a metal ion; a Lewis base."],["Linkage isomerism","Isomerism involving a complex ion where the ligands are all the same but the point of attachment of at least one of the ligands differs."],["Metallurgy","The process of separating a metal from its ore and preparing it for use."],["Mineral","A relatively pure compound as found in nature."],["Monodentate (unidentate) ligand","A ligand that can form one bond to a metal ion."],["Myoglobin","An oxygenstoring biomolecule consisting of a heme complex and a proton."],["Open hearth process","A process for producing steel by oxidizing and removing the impurities in molten iron using external heat and a blast of air or oxygen."],["Optical isomerism","Isomerism in which the isomers have opposite effects on planepolarized light."],["d-orbital splitting","Da splitting of the orbitals of the metal ion in a complex such that the orbitals pointing at the ligands have higher energies than those pointing between the ligands."],["Oxidation states","A concept that provides a way to keep track of electrons in oxidation–reduction reactions according to certain rules."],["Porphyrin","A planar ligand with a central ring structure and various substituent groups at the edges of the ring."],["Pyrometallurgy","Recovery of a metal from its ore by treatment at high temperatures."],["Roasting","A process of converting sulfide minerals to oxides by heating in air at temperatures below their melting points."],["Smelting","A metallurgical process that involves reducing metal ions to the free metal."],["Spectrochemical series","A listing of ligands in order based on their dability to produce -orbital splitting."],["Stereoisomerism","Isomerism in which all the bonds in the isomers are the same but the spatial arrangements of the atoms are different."],["Structural isomerism","Isomerism in which the isomers contain the same atoms but one or more bonds differ."],["Tempering","A process in steel production that finetunes the proportions of carbon crystals and cementite by heating to intermediate temperatures followed by rapid cooling."],["Zone refining","A metallurgical process for obtaining a highly pure metal that depends on continuously melting the impure material and recrystallizing the pure metal."]],"equations":[]},{"number":22,"title":"Organic and Biological Molecules","sections":[{"title":"Alkanes: Saturated Hydrocarbons","topics":[]},{"title":"Alkenes and Alkynes","topics":[]},{"title":"Aromatic Hydrocarbons","topics":[]},{"title":"Hydrocarbon Derivatives","topics":[]},{"title":"Polymers","topics":[]},{"title":"Natural Polymers","topics":[]}],"focusAreas":["Alkanes: Saturated Hydrocarbons","Alkenes and Alkynes","Aromatic Hydrocarbons","Hydrocarbon Derivatives","Polymers","Natural Polymers"],"vocabulary":[["Addition polymerization","A type of polymerization in which the monomers simply add together to form the polymer,with no other products."],["Addition reaction","A reaction in which atoms add to a carbon– carbon multiple bond."],["Alcohol","An organic compound in which the hydroxyl group is a substituent on a hydrocarbon."],["Aldehyde","An organic compound containing the carbonyl group bonded to at least one hydrogen atom."],["α-Amino acid","An organic acid in which an amino group and an R group are attached to the carbon atom next to the carboxyl group."],["Aromatic hydrocarbon","One of a special class of cyclic unsaturated hydrocarbons,the simplest of which is benzene."],["Biomolecule","A molecule responsible for maintaining and/or reproducing life."],["Carbohydrate","A polyhydroxyl ketone or polyhydroxyl aldehyde or a polymer composed of these."],["Carboxylic acid","An organic compound containing the carboxyl group; an acid with the general formula RCOOH."],["Codons","Organic bases in sets of three that form the genetic code."],["Combustion reaction","The vigorous and exothermic reaction that takes place between certain substances,particularly organic compounds, and oxygen."],["Condensation polymerization","A type of polymerization in which the formation of a small molecule,such as water,accompanies the extension of the polymer chain."],["Copolymer","A polymer formed from the polymerization of more than one type of monomer."],["Crosslinking","The existence of bonds between adjacent chains in a polymer,thus adding strength to the material."],["Dehydrogenation reaction","A reaction in which two hydrogen atoms are removed from adjacent carbons of a saturated hydrocarbon,giving an unsaturated hydrocarbon."],["Denaturation","The breaking down of the threedimensional structure of a protein resulting in the loss of its function."],["Deoxyribonucleic acid (DNA)","A huge nucleotide polymer having a doublehelical structure with complementary bases on the two strands. Its major functions are protein synthesis and the storage and transport of genetic information."],["Dimer","A molecule formed by the joining of two identical monomers."],["Disaccharide","A sugar formed from two monosaccharides joined by a glycoside linkage."],["Disulfide linkage","An S S bond that stabilizes the tertiary structureO of many proteins."],["Ester","An organic compound produced by the reaction between a carboxylic acid and an alcohol."],["Free radical","A species with an unpaired electron."],["Functional group","An atom or group of atoms in hydrocarbon derivatives that contains elements in addition to carbon and hydrogen."],["Gene","A given segment of the DNA molecule that contains the code for a specific protein."],["Geometrical (cis–trans) isomerism","Isomerism in which atoms or groups of atoms can assume different positions around a rigid ring or bond."],["Glycoside linkage","A C O C bond formed between the rings of twoO O cyclic monosaccharides by the elimination of water."],["Halogenation","The addition of halogen atoms to unsaturated hydrocarbons."],["Homopolymer","A polymer formed from the polymerization of only one type of monomer."],["Hydrocarbon","A compound composed of carbon and hydrogen."],["Hydrocarbon derivative","An organic molecule that contains one or more elements in addition to carbon and hydrogen."],["Hydrogenation reaction","A reaction in which hydrogen is added,with a catalyst present,to a carbon–carbon multiple bond."],["Messenger RNA (mRNA)","A special RNA molecule built in the cell nucleus that migrates into the cytoplasm and participates in protein synthesis."],["Monosaccharide (simple sugar)","A polyhydroxy ketone or aldehyde containing from three to nine carbon atoms."],["Nucleotide","A monomer of the nucleic acids composed of a fivecarbon sugar,a nitrogencontaining base,and phosphoric acid."],["Organic chemistry","The study of carboncontaining compounds (typically chains of carbon atoms) and their properties."],["Phenyl group","The benzene molecule minus one hydrogen atom."],["Polymer","A large, usually chainlike molecule built from many small molecules (monomers)."],["Polymerization","A process in which many small molecules (monomers) are joined together to form a large molecule."],["Polypeptide","A polymer formed from amino acids joined together by peptide linkages."],["Primary structure (of a protein)","The order (sequence) of amino acids in the protein chain."],["Protein","A natural highmolecularweight polymer formed by condensation reactions between amino acids."],["Ribonucleic acid (RNA)","A nucleotide polymer that transmits the genetic information stored in DNA to the ribosomes for protein synthesis."],["Structural isomerism","Isomerism in which the isomers contain the same atoms but one or more bonds differ."],["Substitution reaction (hydrocarbons)","A reaction in which an atom, usually a halogen, replaces a hydrogen atom in a hydrocarbon."],["Tertiary structure (of a protein)","The overall shape of a protein,long and narrow or globular, maintained by different types of intramolecular interactions."],["Thermoplastic polymer","A substance that when molded to a certain shape under appropriate conditions can later be remelted."],["Thermoset polymer","A substance that when molded to a certain shape under pressure and high temperatures cannot be softened again or dissolved."],["Transfer RNA (tRNA)","A small RNA fragment that finds specific amino acids and attaches them to the protein chain as dictated by the codons in mRNA."]],"equations":[]}]}]};
